import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as notificationRepo from "@/server/repositories/notification-repository";
import { toIsoTimestamp } from "@/types/common";
import type { Page } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

let cleanup: () => void;
let north: Tenant;
let acme: Tenant;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  north = await createTenant("tie-north");
  acme = await createTenant("tie-acme");
});

afterAll(() => {
  cleanup();
});

async function walk<T extends { id: string }>(
  load: (cursor: string | null, limit: number) => Promise<Page<T>>,
  limit: number,
): Promise<readonly string[]> {
  const ids: string[] = [];
  let cursor: string | null = null;
  for (let guard = 0; guard < 50; guard += 1) {
    const page = await load(cursor, limit);
    ids.push(...page.items.map((item) => item.id));
    if (page.nextCursor === null) return ids;
    if (page.nextCursor === cursor) throw new Error("cursor did not advance");
    cursor = page.nextCursor;
  }
  throw new Error("pagination did not terminate");
}

describe("keyset ties", () => {
  it("returns every same-timestamp issue exactly once, in large-page order", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    try {
      const stamp = (minute: number) => new Date(Date.UTC(2026, 4, 2, 12, minute));
      for (const minute of [0, 0, 0, 0, 5, 5, 10]) {
        vi.setSystemTime(stamp(minute));
        const number = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
        await issueRepo.insertIssue(
          issueInput(north.org.id, north.project.id, { title: `North ${minute} ${number}` }),
          north.userIds.owner,
          number,
        );
        const other = await issueRepo.nextIssueNumber(acme.org.id, acme.project.id);
        await issueRepo.insertIssue(
          issueInput(acme.org.id, acme.project.id, { title: `Acme ${minute} ${other}` }),
          acme.userIds.owner,
          other,
        );
      }
    } finally {
      vi.useRealTimers();
    }

    const full = await issueRepo.listIssues({
      orgId: north.org.id,
      limit: 100,
      cursor: null,
    });
    expect(full.total).toBe(7);
    expect(full.items.every((issue) => issue.orgId === north.org.id)).toBe(true);

    for (const limit of [1, 2, 3, 4, 6, 7]) {
      const ids = await walk(
        (cursor, size) =>
          issueRepo.listIssues({ orgId: north.org.id, limit: size, cursor }),
        limit,
      );
      expect(ids).toEqual(full.items.map((issue) => issue.id));
    }
  });

  it("returns every same-timestamp notification exactly once", async () => {
    const at = toIsoTimestamp(new Date("2026-05-02T12:00:00.000Z"));
    vi.useFakeTimers({ toFake: ["Date"] });
    try {
      vi.setSystemTime(new Date(at));
      await notificationRepo.insertNotifications(
        north.org.id,
        Array.from({ length: 7 }, (_, index) => ({
          orgId: north.org.id,
          recipientId: north.userIds.owner,
          kind: "issue_assigned" as const,
          title: `Assigned ${index}`,
          body: "batch",
          href: "/issues/1",
          actorId: north.userIds.admin,
          channels: ["in_app" as const],
        })),
      );
      await notificationRepo.insertNotifications(
        acme.org.id,
        Array.from({ length: 4 }, (_, index) => ({
          orgId: acme.org.id,
          recipientId: acme.userIds.owner,
          kind: "issue_assigned" as const,
          title: `Other ${index}`,
          body: "batch",
          href: "/issues/1",
          actorId: acme.userIds.admin,
          channels: ["in_app" as const],
        })),
      );
    } finally {
      vi.useRealTimers();
    }

    const full = await notificationRepo.listNotifications({
      orgId: north.org.id,
      recipientId: north.userIds.owner,
      limit: 100,
      cursor: null,
    });
    expect(full.total).toBe(7);

    for (const limit of [1, 2, 3, 7]) {
      const ids = await walk(
        (cursor, size) =>
          notificationRepo.listNotifications({
            orgId: north.org.id,
            recipientId: north.userIds.owner,
            limit: size,
            cursor,
          }),
        limit,
      );
      expect(ids).toEqual(full.items.map((row) => row.id));
      expect(new Set(ids).size).toBe(7);
    }
  });

  it("returns every same-timestamp audit event exactly once", async () => {
    const occurredAt = toIsoTimestamp(new Date("2026-05-02T15:00:00.000Z"));
    for (let index = 0; index < 7; index += 1) {
      await activityRepo.insertActivity({
        orgId: north.org.id,
        action: "issue.updated",
        actorId: north.userIds.owner,
        subjectKind: "issue",
        subjectId: `subject-${index}`,
        projectId: north.project.id,
        summary: `bulk ${index}`,
        metadata: {},
        occurredAt,
      });
    }
    for (let index = 0; index < 3; index += 1) {
      await activityRepo.insertActivity({
        orgId: acme.org.id,
        action: "issue.updated",
        actorId: acme.userIds.owner,
        subjectKind: "issue",
        subjectId: `other-${index}`,
        projectId: acme.project.id,
        summary: `other ${index}`,
        metadata: {},
        occurredAt,
      });
    }

    const full = await activityRepo.listActivity({
      orgId: north.org.id,
      limit: 100,
      cursor: null,
    });
    expect(full.total).toBe(7);
    expect(full.items.every((event) => event.orgId === north.org.id)).toBe(true);

    for (const limit of [1, 2, 6]) {
      const ids = await walk(
        (cursor, size) =>
          activityRepo.listActivity({ orgId: north.org.id, limit: size, cursor }),
        limit,
      );
      expect(ids).toEqual(full.items.map((event) => event.id));
    }
  });
});

